//! ES|QL commands, functions, and operators from `catalogs/esql/`.
//!
//! The TOML is generated by `scripts/sync_esql_catalog.py` from Elastic's
//! own definition JSON, the docs `applies_to` lifecycle, and each release
//! branch's grammar and definitions (`versions`). Each file is parsed once per
//! process.

use crate::version::Availability;
use serde::Deserialize;
use std::sync::OnceLock;

const COMMANDS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/esql/commands.toml"
));
const FUNCTIONS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/esql/functions.toml"
));
const OPERATORS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/esql/operators.toml"
));
const TYPES_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/esql/types.toml"
));

#[derive(Debug, Deserialize)]
struct CommandsFile {
    #[serde(default)]
    branches: Vec<String>,
    commands: Vec<CommandRow>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CommandRow {
    pub name: String,
    pub kind: String,
    #[serde(default)]
    pub syntax: String,
    #[serde(default)]
    pub docs: String,
    #[serde(default)]
    pub stack: String,
    /// Release branches that accept the command (`None`: not recorded).
    #[serde(default)]
    pub versions: Option<Vec<String>>,
    #[serde(default)]
    pub snapshot_only: bool,
    #[serde(default)]
    pub citation: Option<String>,
    #[serde(default)]
    pub alias_of: Option<String>,
}

impl CommandRow {
    pub fn availability(&self) -> Option<Availability> {
        self.versions.as_deref().map(Availability::from_versions)
    }
}

#[derive(Debug, Deserialize)]
struct FunctionsFile {
    #[serde(default)]
    branches: Vec<String>,
    functions: Vec<FunctionRow>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct FunctionRow {
    pub name: String,
    pub kind: String,
    pub signature: String,
    #[serde(default)]
    pub docs: String,
    #[serde(default)]
    pub returns: Vec<String>,
    /// Other registered names (`to_str` for `to_string`).
    #[serde(default)]
    pub aliases: Vec<String>,
    #[serde(default)]
    pub stack: String,
    /// Release branches that accept the function (`None`: not recorded).
    #[serde(default)]
    pub versions: Option<Vec<String>>,
    #[serde(default)]
    pub preview: bool,
    #[serde(default)]
    pub snapshot_only: bool,
    #[serde(default)]
    pub license: Option<String>,
    #[serde(default)]
    pub citation: Option<String>,
    #[serde(default)]
    pub example: Option<String>,
    #[serde(default)]
    pub parameters: Vec<ParamRow>,
}

impl FunctionRow {
    pub fn availability(&self) -> Option<Availability> {
        self.versions.as_deref().map(Availability::from_versions)
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct ParamRow {
    pub name: String,
    #[serde(default)]
    pub docs: String,
    #[serde(default)]
    pub types: Vec<String>,
    #[serde(default)]
    pub required: bool,
}

#[derive(Debug, Deserialize)]
struct OperatorsFile {
    operators: Vec<OperatorRow>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct OperatorRow {
    pub name: String,
    pub operator: String,
    #[serde(default)]
    pub docs: String,
    #[serde(default)]
    pub preview: bool,
    #[serde(default)]
    pub citation: Option<String>,
}

#[derive(Debug, Deserialize)]
struct TypesFile {
    #[serde(default)]
    branches: Vec<String>,
    types: Vec<TypeRow>,
}

/// A `::type` cast target and the conversion function it calls.
#[derive(Debug, Clone, Deserialize)]
pub struct TypeRow {
    pub name: String,
    #[serde(default)]
    pub function: String,
    #[serde(default)]
    pub versions: Vec<String>,
}

impl TypeRow {
    pub fn availability(&self) -> Availability {
        Availability::from_versions(&self.versions)
    }
}

#[derive(Debug)]
pub struct Catalog {
    pub commands: Vec<CommandRow>,
    pub functions: Vec<FunctionRow>,
    pub operators: Vec<OperatorRow>,
    pub types: Vec<TypeRow>,
    /// Release branches the `versions` lists were read from.
    pub branches: Vec<String>,
}

impl Catalog {
    pub fn cached() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            let commands: CommandsFile = toml::from_str(COMMANDS_TOML).expect("esql commands");
            let functions: FunctionsFile = toml::from_str(FUNCTIONS_TOML).expect("esql functions");
            let operators: OperatorsFile = toml::from_str(OPERATORS_TOML).expect("esql operators");
            let types: TypesFile = toml::from_str(TYPES_TOML).expect("esql types");
            debug_assert_eq!(commands.branches, functions.branches);
            debug_assert_eq!(commands.branches, types.branches);
            Catalog {
                commands: commands.commands,
                functions: functions.functions,
                operators: operators.operators,
                types: types.types,
                branches: commands.branches,
            }
        })
    }

    /// A command by its canonical lower-case name (`stats`, `lookup join`).
    pub fn command(&self, name: &str) -> Option<&CommandRow> {
        self.commands
            .iter()
            .find(|c| c.name.eq_ignore_ascii_case(name))
    }

    /// Function names are case-insensitive; aliases resolve to their function.
    pub fn function(&self, name: &str) -> Option<&FunctionRow> {
        self.functions.iter().find(|f| {
            f.name.eq_ignore_ascii_case(name)
                || f.aliases.iter().any(|a| a.eq_ignore_ascii_case(name))
        })
    }

    /// A `::type` cast target; names are case-insensitive.
    pub fn cast_type(&self, name: &str) -> Option<&TypeRow> {
        self.types
            .iter()
            .find(|t| t.name.eq_ignore_ascii_case(name))
    }

    pub fn suggest_type(&self, name: &str) -> Option<String> {
        closest(self.types.iter().map(|t| t.name.as_str()), name, 2)
    }

    pub fn operator(&self, symbol: &str) -> Option<&OperatorRow> {
        self.operators
            .iter()
            .find(|o| o.operator.eq_ignore_ascii_case(symbol))
    }

    /// Closest command name within edit distance 3, for `esql_unknown_command`.
    pub fn suggest_command(&self, name: &str) -> Option<String> {
        closest(
            self.commands
                .iter()
                .filter(|c| !c.snapshot_only && c.alias_of.is_none())
                .map(|c| c.name.as_str()),
            name,
            3,
        )
    }

    pub fn suggest_function(&self, name: &str) -> Option<String> {
        closest(
            self.functions
                .iter()
                .filter(|f| !f.snapshot_only)
                .map(|f| f.name.as_str()),
            name,
            2,
        )
    }
}

fn closest<'a>(names: impl Iterator<Item = &'a str>, target: &str, max: usize) -> Option<String> {
    let target = target.to_ascii_lowercase();
    names
        .map(|n| (n, edit_distance(n, &target)))
        .filter(|(_, d)| *d > 0 && *d <= max)
        .min_by_key(|(_, d)| *d)
        .map(|(n, _)| n.to_string())
}

pub(crate) fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for (i, ca) in a.iter().enumerate() {
        let mut cur = vec![i + 1];
        for (j, cb) in b.iter().enumerate() {
            let cost = usize::from(!ca.eq_ignore_ascii_case(cb));
            cur.push((prev[j] + cost).min(prev[j + 1] + 1).min(cur[j] + 1));
        }
        prev = cur;
    }
    prev[b.len()]
}

/// A stack version such as `9.2`. Patch numbers are dropped.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct StackVersion {
    pub major: u32,
    pub minor: u32,
}

impl StackVersion {
    pub const fn new(major: u32, minor: u32) -> Self {
        Self { major, minor }
    }

    pub(crate) fn parse(text: &str) -> Option<Self> {
        let text = text.trim().trim_start_matches('=').trim_end_matches('+');
        let text = text.split('-').next()?;
        let mut parts = text.split('.');
        let major = parts.next()?.trim().parse().ok()?;
        let minor = parts.next().unwrap_or("0").trim().parse().ok()?;
        Some(Self { major, minor })
    }
}

impl std::fmt::Display for StackVersion {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}.{}", self.major, self.minor)
    }
}

/// The opentide floor for Elastic Security ([elastic-1.0] "Kibana 8.19 and 9.x").
///
/// 8.19 shipped beside 9.1 with the same ES|QL feature set, so anything the
/// docs first list at 9.2 or later is missing on 8.19. The 9.x docs start at
/// 9.0; a lifecycle that starts at 9.0 or 9.1 says nothing about 8.19.
pub const FIRST_AFTER_FLOOR: StackVersion = StackVersion::new(9, 2);

/// The `stack:` lifecycle of a command or function in the 9.x docs.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Lifecycle {
    /// First version documented as GA. `None` with `ga_unversioned` means
    /// GA in every documented version.
    pub ga: Option<StackVersion>,
    pub ga_unversioned: bool,
    /// First version documented as technical preview.
    pub preview: Option<StackVersion>,
    pub preview_unversioned: bool,
}

impl Lifecycle {
    /// Parse `preview =9.2, ga 9.3+`, `preview 9.1-9.3, ga 9.4+`, `ga`, `ga 9.4.0`.
    pub fn parse(stack: &str) -> Self {
        let mut lifecycle = Lifecycle::default();
        for entry in stack.split(',') {
            let mut words = entry.split_whitespace();
            let Some(state) = words.next() else {
                continue;
            };
            let version = words.next().and_then(StackVersion::parse);
            match (state, version) {
                ("ga", Some(v)) => lifecycle.ga = Some(lifecycle.ga.map_or(v, |g| g.min(v))),
                ("ga", None) => lifecycle.ga_unversioned = true,
                ("preview" | "beta", Some(v)) => {
                    lifecycle.preview = Some(lifecycle.preview.map_or(v, |p| p.min(v)));
                }
                ("preview" | "beta", None) => lifecycle.preview_unversioned = true,
                _ => {}
            }
        }
        lifecycle
    }

    /// The first version the docs list at all.
    pub fn first(&self) -> Option<StackVersion> {
        match (self.ga, self.preview) {
            (Some(g), Some(p)) => Some(g.min(p)),
            (g, p) => g.or(p),
        }
    }

    pub fn is_ga(&self) -> bool {
        self.ga.is_some() || self.ga_unversioned
    }

    /// Missing on the 8.19 floor: first documented at 9.2 or later.
    pub fn after_floor(&self) -> Option<StackVersion> {
        if self.ga_unversioned || self.preview_unversioned {
            return None;
        }
        self.first().filter(|v| *v >= FIRST_AFTER_FLOOR)
    }

    /// One line for hover text.
    pub fn describe(&self) -> String {
        let mut parts = Vec::new();
        if let Some(p) = self.preview {
            parts.push(format!("technical preview from {p}"));
        } else if self.preview_unversioned && !self.is_ga() {
            parts.push("technical preview".to_string());
        }
        if let Some(g) = self.ga {
            parts.push(format!("GA from {g}"));
        } else if self.ga_unversioned {
            parts.push("GA".to_string());
        }
        parts.join(", ")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_loads_commands_and_functions() {
        let catalog = Catalog::cached();
        assert!(catalog.command("where").is_some());
        assert!(catalog.command("LOOKUP JOIN").is_some());
        assert!(catalog.function("starts_with").is_some());
        assert!(catalog.function("COUNT").is_some());
        assert_eq!(
            catalog.function("TO_STR").map(|f| f.name.as_str()),
            Some("to_string")
        );
        assert_eq!(
            catalog.function("bin").map(|f| f.name.as_str()),
            Some("bucket")
        );
        assert!(catalog.operator("==").is_some());
        assert_eq!(catalog.suggest_command("wehre").as_deref(), Some("where"));
        assert!(catalog.function("abs").is_some(), "math module definitions");
        assert_eq!(
            catalog.cast_type("STRING").map(|t| t.function.as_str()),
            Some("to_string")
        );
    }

    #[test]
    fn versions_cover_the_tracked_releases() {
        use crate::version::RELEASES;
        let catalog = Catalog::cached();
        let tracked: Vec<String> = RELEASES.iter().map(ToString::to_string).collect();
        assert_eq!(catalog.branches, tracked);
        let v = |s: &str| StackVersion::parse(s).unwrap();
        let fork = catalog.command("fork").and_then(CommandRow::availability);
        assert!(fork.is_some_and(|a| !a.contains(v("8.19")) && a.contains(v("9.1"))));
        let sample = catalog.command("sample").and_then(CommandRow::availability);
        assert!(sample.is_some_and(|a| a.contains(v("8.19")) && !a.contains(v("9.0"))));
        let copy_sign = catalog
            .function("copy_sign")
            .and_then(FunctionRow::availability);
        assert!(copy_sign.is_some_and(|a| !a.contains(v("8.19")) && a.contains(v("9.1"))));
        let multi_match = catalog
            .function("multi_match")
            .and_then(FunctionRow::availability);
        assert!(multi_match.is_some_and(|a| a.contains(v("9.3")) && !a.contains(v("9.4"))));
        for f in &catalog.functions {
            assert!(!f.docs.is_empty(), "{} has no summary", f.name);
            assert!(f.versions.is_some(), "{} has no versions", f.name);
        }
        for c in &catalog.commands {
            assert!(c.versions.is_some(), "{} has no versions", c.name);
        }
    }

    #[test]
    fn lifecycle_parses_doc_forms() {
        let l = Lifecycle::parse("preview =9.2, ga 9.3+");
        assert_eq!(l.preview, Some(StackVersion::new(9, 2)));
        assert_eq!(l.ga, Some(StackVersion::new(9, 3)));
        assert_eq!(l.after_floor(), Some(StackVersion::new(9, 2)));
        let l = Lifecycle::parse("preview 9.0-9.3, ga 9.4+");
        assert_eq!(l.first(), Some(StackVersion::new(9, 0)));
        assert_eq!(l.after_floor(), None, "9.0 says nothing about 8.19");
        let l = Lifecycle::parse("ga");
        assert!(l.is_ga());
        assert_eq!(l.after_floor(), None);
        let l = Lifecycle::parse("ga 9.4.0");
        assert_eq!(l.ga, Some(StackVersion::new(9, 4)));
        assert_eq!(l.describe(), "GA from 9.4");
        let l = Lifecycle::parse("ga 9.3+, preview 9.1-9.2");
        assert_eq!(l.describe(), "technical preview from 9.1, GA from 9.3");
    }
}
